def parse_data_entry(entry_str: str) -> Dict[str, Any]:
    """Parse a data entry string into a dictionary"""
    data_dict = {}
    pairs = entry_str.strip("[]").split("', '")
    for pair in pairs:
        pair = pair.strip("'")
        if ':' in pair:
            key, value = pair.split(':', 1)
            data_dict[key] = value
    return data_dict

